Scraper Helpers
The original code requested both manually provided subtitles and automatic captions in English, wrote VTT files temporarily, read them back into the metadata row, and deleted the temporary files. This notebook follows that logic while also recording which subtitle languages were available and downloaded.

class DummyLogger:
    def debug(self, msg):
        pass

    def warning(self, msg):
        pass

    def error(self, msg):
        pass


def validate_scraper_config():
    if IDENTIFYING_USER_AGENT == "YOUR_REGISTERED_TOKEN":
        raise ValueError(
            'Replace IDENTIFYING_USER_AGENT = "YOUR_REGISTERED_TOKEN" with your registered token before scraping.'
        )
    if find_spec("yt_dlp") is None:
        raise ImportError(
            'yt_dlp is not installed. Run: %pip install "yt-dlp[default,curl-cffi]"'
        )


def as_json_text(value):
    if value is None:
        return None
    if isinstance(value, (list, dict)):
        return json.dumps(value, ensure_ascii=False, default=str)
    return value


def comma_join_keys(value):
    if isinstance(value, dict):
        return ",".join(sorted(value.keys()))
    return None


def empty_metadata_row(video_id):
    row = {field: None for field in METADATA_FIELDS}
    row["id"] = video_id
    row["metadata_status"] = "pending"
    row["downloaded_subtitle_file_count"] = 0
    return row


def get_metadata(video_id, quiet=True, no_warnings=True):
    import yt_dlp as yt

    url = f"https://www.youtube.com/watch?v={video_id}"
    ydl_opts = {
        "quiet": quiet,
        "no_warnings": no_warnings,
        "logger": DummyLogger(),
        "skip_download": True,
        "writesubtitles": True,
        "writeautomaticsub": True,
        "subtitlesformat": "vtt",
        "subtitleslangs": SUBTITLE_LANGUAGES,
        "outtmpl": str(SUBTITLES_DIR / video_id),
        "http_headers": {"User-Agent": IDENTIFYING_USER_AGENT},
    }

    row = empty_metadata_row(video_id)

    try:
        with yt.YoutubeDL(ydl_opts) as ydl:
            # download=True allows subtitle files to be written; skip_download=True prevents video download.
            info = ydl.extract_info(url, download=True)

        for field in CORE_METADATA_FIELDS:
            row[field] = as_json_text(info.get(field))

        manual_subtitles = info.get("subtitles") or {}
        automatic_captions = info.get("automatic_captions") or {}
        requested_subtitles = info.get("requested_subtitles") or {}

        row["available_manual_subtitle_languages"] = comma_join_keys(manual_subtitles)
        row["available_auto_caption_languages"] = comma_join_keys(automatic_captions)
        row["requested_subtitles"] = as_json_text(requested_subtitles)

        subtitle_texts = []
        downloaded_languages = []
        for language, subtitle_info in requested_subtitles.items():
            subtitle_file = subtitle_info.get("filepath") if isinstance(subtitle_info, dict) else None
            if subtitle_file and Path(subtitle_file).exists():
                subtitle_text = Path(subtitle_file).read_text(encoding="utf-8")
                subtitle_texts.append(f"WEBVTT_LANGUAGE: {language}\n{subtitle_text}")
                downloaded_languages.append(language)
                try:
                    Path(subtitle_file).unlink()
                except OSError as exc:
                    print(f"Warning: failed to delete subtitle file {subtitle_file}: {exc}")

        row["subtitles"] = "\n\n".join(subtitle_texts) if subtitle_texts else None
        row["downloaded_subtitle_languages"] = ",".join(downloaded_languages) if downloaded_languages else None
        row["downloaded_subtitle_file_count"] = len(downloaded_languages)
        row["metadata_status"] = "ok"

    except Exception as exc:
        # Keep the raw yt_dlp message. These messages often explain why metadata was unavailable.
        row["error"] = str(exc)
        row["metadata_status"] = "error"

    return row

Handle details And Classify Rows
This step follows the validated selection mechanic from the original workflow: a retained video-watch row must have a standard watch URL, an 11-character video_id, and no details value. Rows with details are excluded from video_histories because in the original data this field captured ads and other non-standard watch-history records.
We still detect Google Ads explicitly and save them separately, so readers can inspect what was excluded.

def details_missing(value):
    # This mirrors the original `details.isna()` selection rule.
    # Lists or dictionaries mean Takeout supplied a details field, so the row is not a clean video watch.
    if isinstance(value, (list, dict)):
        return False
    return bool(pd.isna(value))


def has_google_ads_marker(details):
    if not isinstance(details, list):
        return False
    return any(
        isinstance(item, dict) and item.get("name") == "From Google Ads"
        for item in details
    )


watch_histories["details_missing"] = watch_histories["details"].apply(details_missing)
watch_histories["has_google_ads_marker"] = watch_histories["details"].apply(has_google_ads_marker)
watch_histories["is_youtube_music"] = watch_histories["header"].eq("YouTube Music")

video_mask = (
    watch_histories["has_valid_video_id"]
    & watch_histories["details_missing"]
    & ~watch_histories["is_youtube_music"]
)
music_mask = watch_histories["is_youtube_music"]
ad_watch_mask = watch_histories["has_google_ads_marker"]
other_mask = ~(video_mask | music_mask | ad_watch_mask)


def classify_watch_row(row):
    if row["is_youtube_music"]:
        return "youtube_music"
    if row["has_valid_video_id"] and row["details_missing"]:
        return "video_watch"
    if row["has_google_ads_marker"]:
        return "ad_watch"
    if row["has_valid_video_id"]:
        return "video_with_details"
    return "other_watch_row"


watch_histories["watch_row_type"] = watch_histories.apply(classify_watch_row, axis=1)

